// Executed only in a scratch HOME, using the installed SDK loader, without a model.
import assert from 'node:assert/strict';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const { loadExtensions } = await import(pathToFileURL(path.join(process.env.PI_TEST_SDK, 'dist/core/extensions/loader.js')));
const loaded = await loadExtensions([process.argv[2]], process.cwd());
assert.deepEqual(loaded.errors, []);
assert.equal(loaded.extensions.length, 1);
const extension = loaded.extensions[0];
assert.deepEqual([...extension.tools.keys()], ['todo']);
assert.deepEqual([...extension.commands.keys()], ['todos']);
const ctx = { cwd: process.cwd(), hasUI: false, sessionManager: { getSessionId: () => 'sdk-pi-actor' } };
for (const handler of extension.handlers.get('session_start')) await handler({}, ctx);
const tool = extension.tools.get('todo').definition;
const { validateToolArguments } = await import(pathToFileURL(path.join(process.env.PI_TEST_SDK, '../pi-ai/dist/index.js')));
const call = input => tool.execute('probe', validateToolArguments(tool, { name: 'todo', arguments: input }), undefined, undefined, ctx);
assert.throws(() => call({ action: 'get', actorId: 'spoof' }), /Validation failed/);
const missingId = await call({ action: 'get' });
assert.equal(missingId.content[0].text, 'Error: id required');
assert.equal(missingId.details.error, 'id required');
const created = await call({ action: 'create', title: 'SDK synthetic', body: 'notes' });
assert.match(created.content[0].text, /"id": "TODO-[a-f0-9]{8}"/);
const id = created.details.todo.id;
const { resolveTaskStore } = await import(pathToFileURL(path.join(path.dirname(process.argv[2]), 'scope.ts')));
const { loadTaskPackage } = await import(pathToFileURL(path.join(path.dirname(process.argv[2]), 'package.mjs')));
const core = await loadTaskPackage('core');
const expectedStore = resolveTaskStore(ctx.cwd, process.env.PI_TODO_PATH ?? '', path.join(process.env.HOME, '.pi/history'));
const direct = await core.executeTask({ action: 'get', id }, { storeRoot: expectedStore, actorId: 'scope-verifier', allowForce: false, allowedActions: ['get'] });
assert.equal(direct.todo.title, 'SDK synthetic', 'actual Pi tool reaches captured default/relative/absolute store');
assert.equal((await call({ action: 'claim', id })).details.todo.assigned_to_session, 'sdk-pi-actor');
await call({ action: 'update', id, status: 'done' });
assert.equal((await call({ action: 'list' })).details.todos.length, 0);
assert.equal((await call({ action: 'list-all' })).details.todos.length, 1);
const command = extension.commands.get('todos');
const completions = await command.getArgumentCompletions('SDK');
assert.equal(completions.length, 1, 'closed tasks remain available in UI completions');
let text = '';
const original = console.log; console.log = value => { text = value; };
try { await command.handler('', ctx); } finally { console.log = original; }
assert.match(text, /Closed todos \(1\)/);
const theme = { fg: (_color, value) => value };
const rendered = tool.renderResult(await call({ action: 'get', id }), { expanded: true }, theme);
assert.ok(rendered.render(100).join('\n').includes('SDK synthetic'));
console.log('PASS: SDK-loaded single todo registration, lifecycle, tool output, closed UI listing/completion and renderer');
